INSERT INTO public.flashcards
  (id1, cn, pinyin, vocabulary, pinyin_vocab, th, sentence_test, translate, pinyin_sentence)
VALUES
(1201, '甩', 'shuǎi', '甩卖', 'shuǎi mài', 'ลดล้างสต๊อก/ขายเทกระจาด', '商场里有一个店铺在甩卖商品。', 'ในห้างมีร้านหนึ่งกำลังลดล้างสต๊อกสินค้า', 'shāng chǎng lǐ yǒu yí gè diàn pù zài shuǎi mài shāng pǐn'),
(1202, '拦', 'lán', '拦路虎', 'lán lù hǔ', 'อุปสรรคขวางทาง', '自大是成长路上的拦路虎。', 'ความหยิ่งยโสคืออุปสรรคขวางทางบนเส้นทางเติบโต', 'zì dà shì chéng zhǎng lù shàng de lán lù hǔ'),
(1203, '降', 'jiàng', '降落', 'jiàng luò', 'ลงจอด/ร่อนลง', '飞机马上要降落了！', 'เครื่องบินกำลังจะลงจอดแล้ว!', 'fēi jī mǎ shàng yào jiàng luò le'),
(1204, '胆', 'dǎn', '胆子', 'dǎn zi', 'ความกล้า/ใจกล้า', '哥哥的胆子很大。', 'พี่ชายกล้ามาก', 'gē ge de dǎn zi hěn dà'),
(1205, '踪', 'zōng', '踪迹', 'zōng jì', 'ร่องรอย', '小偷没留下任何踪迹。', 'ขโมยไม่ทิ้งร่องรอยใดๆ ไว้เลย', 'xiǎo tōu méi liú xià rèn hé zōng jì'),
(1206, '决', 'jué', '决定', 'jué dìng', 'ตัดสินใจ', '他决定下周回北京。', 'เขาตัดสินใจจะกลับปักกิ่งสัปดาห์หน้า', 'tā jué dìng xià zhōu huí běi jīng'),
(1207, '刺', 'cì', '刺耳', 'cì ěr', 'บาดหู/แสบหู', '路边的噪音非常刺耳。', 'เสียงรบกวนข้างถนนบาดหูมาก', 'lù biān de zào yīn fēi cháng cì ěr'),
(1208, '汤', 'tāng', '鱼汤', 'yú tāng', 'ซุปปลา', '我们都喜欢喝奶奶做的鱼汤。', 'พวกเราชอบกินซุปปลาที่คุณย่าทำ', 'wǒ men dōu xǐ huān hē nǎi nai zuò de yú tāng'),
(1209, '茶', 'chá', '花茶', 'huā chá', 'ชาดอกไม้', '奶奶喜欢喝花茶。', 'คุณย่าชอบดื่มชาดอกไม้', 'nǎi nai xǐ huān hē huā chá'),
(1210, '粽', 'zòng', '粽子', 'zòng zi', 'บ๊ะจ่าง', '端午节要吃粽子。', 'เทศกาลตวนอู่ต้องกินบ๊ะจ่าง', 'duān wǔ jié yào chī zòng zi'),
(1211, '察', 'chá', '观察', 'guān chá', 'สังเกต', '科学家正在观察一只小白鼠。', 'นักวิทยาศาสตร์กำลังสังเกตหนูขาวตัวหนึ่ง', 'kē xué jiā zhèng zài guān chá yì zhī xiǎo bái shǔ'),
(1212, '扇', 'shàn', '扇子', 'shàn zi', 'พัด', '夏天要用扇子扇风。', 'ฤดูร้อนต้องใช้พัดโบกลม', 'xià tiān yào yòng shàn zi shān fēng'),
(1213, '猛', 'měng', '凶猛', 'xiōng měng', 'ดุร้าย', '动物园里有一只非常凶猛的老虎。', 'ในสวนสัตว์มีเสือที่ดุร้ายมากตัวหนึ่ง', 'dòng wù yuán lǐ yǒu yì zhī fēi cháng xiōng měng de lǎo hǔ'),
(1214, '萤', 'yíng', '萤火虫', 'yíng huǒ chóng', 'หิ่งห้อย', '夜晚，天空中有很多萤火虫。', 'ยามค่ำคืน บนท้องฟ้ามีหิ่งห้อยมากมาย', 'yè wǎn, tiān kōng zhōng yǒu hěn duō yíng huǒ chóng'),
(1215, '贵', 'guì', '贵州', 'guì zhōu', 'กุ้ยโจว (มณฑล)', '贵州是中国的一个省。', 'กุ้ยโจวเป็นมณฑลหนึ่งของจีน', 'guì zhōu shì zhōng guó de yí gè shěng'),
(1216, '评', 'píng', '评比', 'píng bǐ', 'ประเมินเปรียบเทียบ/ประกวด', '经过评比，姐姐得了认字大赛第一名。', 'หลังการประกวด พี่สาวได้ที่หนึ่งในการแข่งอ่านตัวอักษร', 'jīng guò píng bǐ, jiě jie dé le rèn zì dà sài dì yī míng'),
(1217, '钱', 'qián', '钱包', 'qián bāo', 'กระเป๋าสตางค์', '我的钱包很可爱。', 'กระเป๋าสตางค์ของฉันน่ารักมาก', 'wǒ de qián bāo hěn kě ài'),
(1218, '孔', 'kǒng', '面孔', 'miàn kǒng', 'ใบหน้า', '这个面孔好熟悉。', 'ใบหน้านี้คุ้นเคยจัง', 'zhè ge miàn kǒng hǎo shú xī'),
(1219, '掌', 'zhǎng', '鼓掌', 'gǔ zhǎng', 'ปรบมือ', '表演一结束，观众开始鼓掌。', 'พอการแสดงจบ ผู้ชมก็เริ่มปรบมือ', 'biǎo yǎn yì jié shù, guān zhòng kāi shǐ gǔ zhǎng'),
(1220, '虽', 'suī', '虽然', 'suī rán', 'ถึงแม้ว่า', '虽然山很高，但我们还是爬上去了！', 'ถึงแม้ภูเขาจะสูง แต่พวกเราก็ปีนขึ้นไปจนได้!', 'suī rán shān hěn gāo, dàn wǒ men hái shì pá shàng qù le'),
(1221, '刷', 'shuā', '印刷', 'yìn shuā', 'การพิมพ์', '印刷术是我国的伟大发明。', 'เทคนิคการพิมพ์เป็นสิ่งประดิษฐ์อันยิ่งใหญ่ของประเทศเรา', 'yìn shuā shù shì wǒ guó de wěi dà fā míng'),
(1222, '洗', 'xǐ', '擦洗', 'cā xǐ', 'เช็ดล้าง', '妈妈正在擦洗桌子。', 'แม่กำลังเช็ดล้างโต๊ะ', 'mā mā zhèng zài cā xǐ zhuō zi'),
(1223, '皂', 'zào', '肥皂', 'féi zào', 'สบู่', '肥皂可以用来洗衣服。', 'สบู่ใช้ซักเสื้อผ้าได้', 'féi zào kě yǐ yòng lái xǐ yī fú'),
(1224, '遍', 'biàn', '遍地', 'biàn dì', 'ทั่วพื้น/เต็มไปหมด', '山上遍地都是野花。', 'บนภูเขาเต็มไปด้วยดอกไม้ป่าทั่วทั้งพื้น', 'shān shàng biàn dì dōu shì yě huā'),
(1225, '检', 'jiǎn', '体检', 'tǐ jiǎn', 'ตรวจร่างกาย', '我们每年都会体检。', 'พวกเราตรวจร่างกายกันทุกปี', 'wǒ men měi nián dōu huì tǐ jiǎn'),
(1226, '署', 'shǔ', '防署', 'fáng shǔ', 'ป้องกันความร้อน (防暑)', '夏天来了，要注意防署。', 'ฤดูร้อนมาถึงแล้ว ต้องระวังป้องกันความร้อน', 'xià tiān lái le, yào zhù yì fáng shǔ'),
(1227, '旅', 'lǚ', '旅途', 'lǚ tú', 'การเดินทาง', '这次旅途很劳累。', 'การเดินทางครั้งนี้เหนื่อยมาก', 'zhè cì lǚ tú hěn láo lèi'),
(1228, '晶', 'jīng', '亮晶晶', 'liàng jīng jīng', 'แวววาว/ระยิบระยับ', '天上的星星亮晶晶，真好看！', 'ดวงดาวบนฟ้าส่องแสงระยิบระยับ สวยจริงๆ!', 'tiān shàng de xīng xīng liàng jīng jīng, zhēn hǎo kàn'),
(1229, '杉', 'shān', '云杉', 'yún shān', 'ต้นสนสปรูซ', '云杉是一种珍贵的树。', 'ต้นสนสปรูซเป็นต้นไม้ที่ล้ำค่าชนิดหนึ่ง', 'yún shān shì yì zhǒng zhēn guì de shù'),
(1230, '桦', 'huà', '白桦林', 'bái huà lín', 'ป่าเบิร์ชขาว', '山上有一片美丽的白桦林。', 'บนภูเขามีป่าเบิร์ชขาวที่งดงามผืนหนึ่ง', 'shān shàng yǒu yí piàn měi lì de bái huà lín'),
(1231, '裙', 'qún', '裙子', 'qún zi', 'กระโปรง', '妈妈穿着一条粉色的裙子。', 'แม่สวมกระโปรงสีชมพูตัวหนึ่ง', 'mā mā chuān zhe yì tiáo fěn sè de qún zi'),
(1232, '脖', 'bó', '脖子', 'bó zi', 'คอ', '天鹅的脖子又长又好看。', 'คอของหงส์ทั้งยาวทั้งสวย', 'tiān é de bó zi yòu cháng yòu hǎo kàn'),
(1233, '臂', 'bì', '手臂', 'shǒu bì', 'แขน', '爸爸的手臂很壮实。', 'แขนของพ่อแข็งแรงล่ำสัน', 'bà ba de shǒu bì hěn zhuàng shí'),
(1234, '镜', 'jìng', '镜子', 'jìng zi', 'กระจก', '我有一面好看的小镜子。', 'ฉันมีกระจกบานเล็กสวยๆ อยู่บานหนึ่ง', 'wǒ yǒu yí miàn hǎo kàn de xiǎo jìng zi'),
(1235, '鬼', 'guǐ', '鬼脸', 'guǐ liǎn', 'ทำหน้าตลก/หน้าผี', '爸爸喜欢扮鬼脸逗小孩。', 'พ่อชอบทำหน้าตลกหยอกล้อเด็กๆ', 'bà ba xǐ huān bàn guǐ liǎn dòu xiǎo hái'),
(1236, '据', 'jù', '根据', 'gēn jù', 'อ้างอิงจาก/ตาม', '这个电影是根据真实故事改编的。', 'หนังเรื่องนี้ดัดแปลงจากเรื่องจริง', 'zhè ge diàn yǐng shì gēn jù zhēn shí gù shì gǎi biān de'),
(1237, '反', 'fǎn', '反光', 'fǎn guāng', 'สะท้อนแสง', '在阳光下镜子会反光。', 'ใต้แสงแดด กระจกจะสะท้อนแสง', 'zài yáng guāng xià jìng zi huì fǎn guāng'),
(1238, '戴', 'dài', '佩戴', 'pèi dài', 'สวมใส่/ประดับ', '军人都要佩戴肩章。', 'ทหารทุกคนต้องติดอินทรธนู', 'jūn rén dōu yào pèi dài jiān zhāng'),
(1239, '详', 'xiáng', '详细', 'xiáng xì', 'ละเอียด', '老师说要把故事写得详细点。', 'คุณครูบอกว่าให้เขียนเรื่องให้ละเอียดขึ้นหน่อย', 'lǎo shī shuō yào bǎ gù shì xiě de xiáng xì diǎn'),
(1240, '猜', 'cāi', '猜一猜', 'cāi yī cāi', 'ลองทายดู', '小白不见了，猜一猜他藏在哪里了？', 'เจ้าไป๋หายไป ลองทายดูสิว่ามันซ่อนอยู่ที่ไหน?', 'xiǎo bái bú jiàn le, cāi yī cāi tā cáng zài nǎ lǐ le'),
(1241, '梧', 'wú', '梧桐', 'wú tóng', 'ต้นอู๋ถง (ต้นไม้)', '我家门前有一棵梧桐树。', 'หน้าบ้านฉันมีต้นอู๋ถงอยู่ต้นหนึ่ง', 'wǒ jiā mén qián yǒu yì kē wú tóng shù'),
(1242, '桐', 'tóng', '油桐', 'yóu tóng', 'ต้นน้ำมันถง', '夏天，我喜欢在油桐树下乘凉。', 'ฤดูร้อน ฉันชอบนั่งพักผ่อนใต้ต้นน้ำมันถง', 'xià tiān, wǒ xǐ huān zài yóu tóng shù xià chéng liáng'),
(1243, '疆', 'jiāng', '疆土', 'jiāng tǔ', 'ดินแดน/อาณาเขต', '解放军战士保卫着我们的疆土。', 'เหล่าทหารปลดแอกปกป้องดินแดนของเรา', 'jiě fàng jūn zhàn shì bǎo wèi zhe wǒ men de jiāng tǔ'),
(1244, '桂', 'guì', '桂花', 'guì huā', 'ดอกหอมหมื่นลี้', '公园里的桂花闻起来真香呀！', 'ดอกหอมหมื่นลี้ในสวนหอมจริงๆ!', 'gōng yuán lǐ de guì huā wén qǐ lái zhēn xiāng ya'),
(1245, '桑', 'sāng', '桑叶', 'sāng yè', 'ใบหม่อน', '蚕宝宝最喜欢吃桑叶。', 'หนอนไหมชอบกินใบหม่อนที่สุด', 'cán bǎo bao zuì xǐ huān chī sāng yè'),
(1246, '麦', 'mài', '麦子', 'mài zi', 'ข้าวสาลี', '地里长满了麦子。', 'ในไร่เต็มไปด้วยข้าวสาลี', 'dì lǐ zhǎng mǎn le mài zi'),
(1247, '塘', 'táng', '池塘', 'chí táng', 'สระน้ำ', '我家门前有一个大池塘。', 'หน้าบ้านฉันมีสระน้ำใหญ่อยู่สระหนึ่ง', 'wǒ jiā mén qián yǒu yí gè dà chí táng'),
(1248, '麻', 'má', '麻雀', 'má què', 'นกกระจอก', '呀，有只麻雀落在了窗台上。', 'อุ๊ย มีนกกระจอกตัวหนึ่งมาเกาะที่ขอบหน้าต่าง', 'ya, yǒu zhī má què luò zài le chuāng tái shàng'),
(1249, '幅', 'fú', '幅度', 'fú dù', 'ระดับ/ขนาด (การเปลี่ยนแปลง)', '今年小麦的收成增长幅度很大。', 'ปีนี้ผลผลิตข้าวสาลีเพิ่มขึ้นในระดับที่มาก', 'jīn nián xiǎo mài de shōu chéng zēng zhǎng fú dù hěn dà'),
(1250, '锦', 'jǐn', '锦旗', 'jǐn qí', 'ธงเกียรติยศ', '我们给英雄送了一面锦旗。', 'พวกเรามอบธงเกียรติยศให้วีรบุรุษหนึ่งผืน', 'wǒ men gěi yīng xióng sòng le yí miàn jǐn qí');
